public class VersionTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String render(java.util.List<Version> list) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(list.get(i).getMajor()).append(".").append(list.get(i).getMinor());
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        check("2.3 vs 2.11 is negative", -1, Integer.signum(new Version(2, 3).compareTo(new Version(2, 11))));
        check("3.0 vs 2.9 is positive", 1, Integer.signum(new Version(3, 0).compareTo(new Version(2, 9))));
        check("1.4 vs 1.4 is zero", 0, Integer.signum(new Version(1, 4).compareTo(new Version(1, 4))));
        check("1.9 vs 2.0 is negative", -1, Integer.signum(new Version(1, 9).compareTo(new Version(2, 0))));

        java.util.List<Version> list = new java.util.ArrayList<>();
        list.add(new Version(2, 11));
        list.add(new Version(1, 9));
        list.add(new Version(2, 3));
        list.add(new Version(1, 0));
        list.add(new Version(3, 1));
        java.util.Collections.sort(list);
        check("Collections.sort order", "[1.0, 1.9, 2.3, 2.11, 3.1]", render(list));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

